"use client";

import { useEffect, useState } from "react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid,
} from "recharts";

export default function Dashboard() {
  const [petitions, setPetitions] = useState<any[]>([]);
  const [selectedCity, setSelectedCity] = useState("");

  useEffect(() => {
    fetchPetitions();
  }, [selectedCity]);

  const fetchPetitions = async () => {
    let url = "http://127.0.0.1:5000/api/petitions";

    if (selectedCity) {
      url += `?location=${selectedCity}`;
    }

    const res = await fetch(url, { cache: "no-store" });
    const data = await res.json();
    setPetitions(data);
  };

  const active = petitions.filter(p => p.status === "active").length;
  const underReview = petitions.filter(p => p.status === "under review").length;
  const closed = petitions.filter(p => p.status === "closed").length;

  const chartData = [
    { name: "Active", value: active },
    { name: "Under Review", value: underReview },
    { name: "Closed", value: closed },
  ];

  return (
    <div className="min-h-screen bg-slate-900 text-white p-10">
      <h1 className="text-3xl font-bold mb-8">City Dashboard</h1>

      {/* City Selector */}
      <div className="mb-8">
        <select
          onChange={(e) => setSelectedCity(e.target.value)}
          className="border border-slate-600 bg-slate-800 text-white p-2 rounded-lg"
        >
          <option value="">All Cities</option>
          <option value="Chennai">Chennai</option>
          <option value="Bangalore">Bangalore</option>
          <option value="Hyderabad">Hyderabad</option>
          <option value="Mumbai">Mumbai</option>
          <option value="Delhi">Delhi</option>
          <option value="Kolkata">Kolkata</option>
          <option value="Pune">Pune</option>
          <option value="Coimbatore">Coimbatore</option>
          <option value="Madurai">Madurai</option>
          <option value="Ahmedabad">Ahmedabad</option>
        </select>
      </div>

      {/* Bar Chart Section */}
      <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 shadow-lg">
        <h2 className="text-xl font-semibold mb-6">
          Petition Status Overview
        </h2>

        <div style={{ width: "100%", height: 350 }}>
          <ResponsiveContainer>
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
              <XAxis dataKey="name" stroke="#cbd5e1" />
              <YAxis stroke="#cbd5e1" allowDecimals={false} />
              <Tooltip />
              <Bar dataKey="value" fill="#3b82f6" radius={[8, 8, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
}